 public static BackupTarget ByCode(string code){return Items().SingleOrDefault(t=>t.Code==code);}
 public static BackupTarget Concrete(string group,bool ready){var list=Items().Where(t=>t.Unit.Contains("m.")||BackupMapping.Unit(t.Unit)=="m3").Where(t=>(t.Code.StartsWith("900")||t.Code.StartsWith("901"))&&(t.Description.IndexOf("Ready Mix",StringComparison.OrdinalIgnoreCase)>=0)==ready);Func<string,bool> match=d=>group=="SlabOnFill"?d.Contains("SLABONFILL"):group=="Structural"?d.Contains("TIEBEAM"):group=="RoofWaterproof"?d.Contains("WATERPROOFINGADMIXTURE"):group=="Footing"?d.Contains("FORFOOTING"):group=="Miscellaneous"?d.Contains("STIFFENERCOLUMN"):group=="WallFooting"?d.Contains("FORWALLFOOTING"):group=="Seal"?d.Contains("SEALCONCRETE"):group=="Lean"&&d.StartsWith("LEANCONCRETE");return list.SingleOrDefault(t=>match(new string(t.Description.ToUpperInvariant().Where(char.IsLetterOrDigit).ToArray())));}
